  Lemma fmA_dec4 : forall d0 s1 s2 out o0 s1a d1 o1 s2a d2 o2 s1b d3 o3 s2b d4 mm (junk : list byte) (P : Z)
                          (xra t2 a2 a3 s5 s6 s7 s10 t3 t5 t6 : word),
    decode_sym d true s1 d0 = Ok (o0, s1a, d1) -> decode_sym d true s2 d1 = Ok (o1, s2a, d2) ->
