  (* [comment removed for export] *)
  Definition fmA_inv (m1 : amem) (out : list Z) : Prop :=
    (exists junk, u8arr asegs m1 DST (map (Z_to_bv 8) out ++ junk) /\ zlen junk = dcap - zlen out)
    /\ munch [(DST, DST + dcap)] m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.
  Definition fmA_ok (x : dec) : Prop :=
    bitd_ok bs (de_bd x) /\ bd_bits (de_bd x) <= 64 /\ zlen (de_out x) <= dcap /\ Forall (fun c => 0 <= c < 256) (de_out x).
  Definition fmA_okr (x : dec) : Prop :=
    bitd_ok bs (de_bd x) /\ bd_bits (de_bd x) <= 2^29 /\ zlen (de_out x) <= dcap /\ Forall (fun c => 0 <= c < 256) (de_out x).

  Notation HEADF x mm xra t2 a2 a3 s5 s6 s7 s10 t3 t5 t6 :=
    (STF 0x96f3c mm xra (Z_to_bv 64 (bd_cont (de_bd x))) t2 (Z_to_bv 64 (S0 + bd_ptr (de_bd x))) (Z_to_bv 64 (DST + zlen (de_out x)))
         a2 a3 (Z_to_bv 64 (de_s2 x)) (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (DST + zlen (de_out x))) s5 s6 s7 s10 t3
         (Z_to_bv 64 (de_s1 x)) t5 t6).
  Definition fmA_K (r : dec) : Prop :=
    forall m2 (y1 y7 y10 y11 y12 y13 y21 y22 y23 y26 y28 y30 y31 : word), fmA_okr r -> fmA_inv m2 (de_out r) ->
      if bd_zero (de_bd r) then
        evtF asegs RNG Q (STF 0x976a0 m2 y1 (Z_to_bv 64 (bd_cont (de_bd r))) y7 y10 y11 y12 y13 (Z_to_bv 64 (de_s2 r))
                            (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (DST + zlen (de_out r))) y21 y22 y23 y26 y28
                            (Z_to_bv 64 (de_s1 r)) y30 y31)
      else
        evtF asegs RNG Q (STF 0x972f4 m2 y1 (Z_to_bv 64 (bd_cont (de_bd r))) y7 (Z_to_bv 64 (S0 + bd_ptr (de_bd r))) y11 y12 y13
                            (Z_to_bv 64 (de_s2 r)) (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (DST + zlen (de_out r))) y21 y22
                            y23 y26 y28 (Z_to_bv 64 (de_s1 r)) y30 y31).

  (* [comment removed for export] *)
  Lemma fmA_after : forall f out s1 s2 c b p r m1 (xra t2 a2 a3 s5 s6 s7 s10 t3 t5 t6 : word),
    (forall x' r' m1' (xra' t2' a2' a3' s5' s6' s7' s10' t3' t5' t6' : word),
       main_loop bs d dcap true f x' = Ok r' -> fmA_ok x' -> fmA_inv m1' (de_out x') -> fmA_K r' ->
       evtF asegs RNG Q (HEADF x' m1' xra' t2' a2' a3' s5' s6' s7' s10' t3' t5' t6')) ->
    RF_huf_fdw_fm.fml_body dcap bs d f (mkDec out s1 s2 (mkBD c b p false)) Unfinished (mkBD c b p false) = Ok r ->
    bitd_ok bs (mkBD c b p false) -> b <= 64 -> zlen out < dcap - 3 -> Forall (fun c => 0 <= c < 256) out ->
    fmA_inv m1 out -> fmA_K r ->
    evtF asegs RNG Q (STF 0x9700c m1 xra (Z_to_bv 64 c) t2 (Z_to_bv 64 (S0 + p)) (Z_to_bv 64 (DST + zlen out)) a2 a3
                         (Z_to_bv 64 s2) (Z_to_bv 64 b) (Z_to_bv 64 (DST + zlen out)) s5 s6 s7 s10 t3 (Z_to_bv 64 s1) t5 t6).
